s("signin_resendIn", "{seconds, plural, =1{You can ask for a fresh code in 1 s} other{You can ask for a fresh code in {seconds} s}}", "Quiet label on the disabled resend button during its 30-second cooldown. 's' = seconds.", "{seconds, plural, =1{1 సెకనులో కొత్త కోడ్ అడగవచ్చు} other{{seconds} సెకన్లలో కొత్త కోడ్ అడగవచ్చు}}", "{seconds, plural, =1{1 second lo kotta code adagochu} other{{seconds} seconds lo kotta code adagochu}}", INT("seconds"), hi="{seconds, plural, =1{1 सेकंड में नया कोड माँगा जा सकता है} other{{seconds} सेकंड में नया कोड माँगा जा सकता है}}", hl="{seconds, plural, =1{1 second mein naya code maanga ja sakta hai} other{{seconds} second mein naya code maanga ja sakta hai}}")
s("signin_freshSent", "A fresh code is on its way.", "Shown after the person asked for a fresh sign-in code and it was sent.", "కొత్త కోడ్ వస్తోంది.", "Kotta code vastondi.", hi="नया कोड आ रहा है।", hl="Naya code aa raha hai.")

# ---- deletion pending: "Keep my account?" (contracts/api/v1.md) ------------
s("acct_pendingTitle", "Keep your account?", "Title of the choice shown when the signed-in account is scheduled for deletion (7-day grace).", "మీ ఖాతాను ఉంచుకుంటారా?", "Mee account ni unchukuntaara?", hi="अपना अकाउंट रखना है?", hl="Apna account rakhna hai?")
s("acct_pendingBody", "Your account is set to be deleted on {date}. Keep it?", "Deletion is scheduled; {date} is a formatted date. Calm, no pressure.", "మీ ఖాతా {date}న తొలగించబడేలా సెట్ అయి ఉంది. దాన్ని ఉంచుకుంటారా?", "Mee account {date} na delete ayyela set ayyi undi. Daanni unchukuntaara?", STR("date"), hi="आपका अकाउंट {date} को डिलीट होना तय है। क्या इसे रखना है?", hl="Aapka account {date} ko delete hona tay hai. Kya ise rakhna hai?")
s("acct_pendingBodySoon", "Your account is set to be deleted soon. Keep it?", "Deletion is scheduled but the date isn't known yet (offline).", "మీ ఖాతా త్వరలో తొలగించబడేలా సెట్ అయి ఉంది. దాన్ని ఉంచుకుంటారా?", "Mee account tvaralo delete ayyela set ayyi undi. Daanni unchukuntaara?", hi="आपका अकाउंट जल्द ही डिलीट होना तय है। क्या इसे रखना है?", hl="Aapka account jald hi delete hona tay hai. Kya ise rakhna hai?")
s("acct_keep", "Keep my account", "Cancels the scheduled deletion.", "నా ఖాతాను ఉంచండి", "Naa account ni unchandi", hi="मेरा अकाउंट रखें", hl="Mera account rakhein")
s("acct_letGo", "Let it go", "Leaves the deletion scheduled and signs out of this phone (clears it).", "వదిలేయండి", "Vadileyandi", hi="जाने दें", hl="Jaane dein")
s("acct_keepFailed", "That didn't go through, so nothing has changed yet. Try again when you're connected.", "Cancelling the deletion failed. No blame.", "అది జరగలేదు, కాబట్టి ఇంకా ఏమీ మారలేదు. కనెక్ట్ అయ్యాక మళ్ళీ ప్రయత్నించండి.", "Adi jaragaledu, kabatti inka emi maaraledu. Connect ayyaaka malli try cheyandi.", hi="यह नहीं हो पाया, इसलिए अभी कुछ नहीं बदला है। कनेक्ट होने पर फिर से कोशिश करें।", hl="Yeh nahi ho paaya, isliye abhi kuch nahi badla hai. Connect hone par phir se try karein.")

# ---- delete account screen (REQ-ACC-11, Apple 5.1.1(v)) --------------------
s("acct_deleteTitle", "Delete my account", "Settings row, screen title and the destructive button. Explicit, not softened.", "నా ఖాతాను తొలగించండి", "Naa account ni delete cheyandi", hi="मेरा अकाउंट डिलीट करें", hl="Mera account delete karein")
s("acct_deleteIntro", "Deleting your account removes:", "Lead-in to the list of what is deleted.", "మీ ఖాతాను తొలగిస్తే ఇవి పోతాయి:", "Mee account delete cheste ivi pothaayi:", hi="अकाउंट डिलीट करने पर ये सब हट जाएगा:", hl="Account delete karne par yeh sab hat jayega:")
s("acct_itemCheckIns", "Your check-ins and notes", "What is deleted (list item).", "మీ చెక్-ఇన్‌లు, నోట్స్", "Mee check-ins, notes", hi="आपके चेक-इन और नोट", hl="Aapke check-ins aur notes")
s("acct_itemHabits", "Your habits", "What is deleted (list item).", "మీ అలవాట్లు", "Mee habits", hi="आपकी आदतें", hl="Aapki habits")
s("acct_itemProgress", "Your Starlight and your Aura's growth", "What is deleted (list item). Starlight and Aura are brand terms.", "మీ Starlight, మీ Aura ఎదుగుదల", "Mee Starlight, mee Aura edugudala", hi="आपका Starlight और आपके Aura का बढ़ना", hl="Aapka Starlight aur aapke Aura ki growth")
s("acct_itemAccount", "Your account and the email you sign in with", "What is deleted (list item).", "మీ ఖాతా, మీరు సైన్ ఇన్ చేసే ఈమెయిల్", "Mee account, meeru sign in chese email", hi="आपका अकाउंट और साइन इन वाला ईमेल", hl="Aapka account aur sign in wala email")
s("acct_grace", "You have 7 days to change your mind. Sign in again before then and everything stays. After that it's deleted for good and can't be brought back.", "The 7-day grace period.", "మనసు మార్చుకోవడానికి మీకు 7 రోజులు ఉన్నాయి. ఆలోపు మళ్ళీ సైన్ ఇన్ చేస్తే అన్నీ అలాగే ఉంటాయి. ఆ తర్వాత అది శాశ్వతంగా తొలగిపోతుంది, తిరిగి తీసుకురాలేం.", "Manasu maarchukovadaaniki meeku 7 rojulu unnaayi. Aalopu malli sign in cheste anni alaage untaayi. Aa tarvaata adi shaashvatanga delete aipotundi, tirigi teesukuraalemu.", hi="मन बदलने के लिए आपके पास 7 दिन हैं। उससे पहले फिर से साइन इन करें, तो सब कुछ बना रहेगा। उसके बाद यह हमेशा के लिए डिलीट हो जाएगा और वापस नहीं लाया जा सकेगा।", hl="Mann badalne ke liye aapke paas 7 din hain. Usse pehle phir se sign in karein, to sab kuch bana rahega. Uske baad yeh hamesha ke liye delete ho jayega aur wapas nahi laaya ja sakega.")
s("acct_store", "If you pay for a subscription through the App Store or Google Play, deleting your account doesn't cancel it. Manage or cancel it in your store's subscription settings.", "Store subscription warning (Apple 5.1.1(v)). Store names stay in English.", "మీరు App Store లేదా Google Play ద్వారా సబ్‌స్క్రిప్షన్ చెల్లిస్తుంటే, ఖాతాను తొలగించినా అది రద్దు కాదు. దాన్ని మీ స్టోర్ సబ్‌స్క్రిప్షన్ సెట్టింగ్‌లలో నిర్వహించండి లేదా రద్దు చేయండి.", "Meeru App Store leda Google Play dwaara subscription pay chestunte, account delete chesina adi cancel avvadu. Daanni mee store subscription settings lo manage cheyandi leda cancel cheyandi.", hi="अगर किसी सब्सक्रिप्शन का पेमेंट App Store या Google Play से होता है, तो अकाउंट डिलीट करने से वह रद्द नहीं होता। उसे अपने स्टोर की सब्सक्रिप्शन सेटिंग्स में मैनेज या रद्द करें।", hl="Agar kisi subscription ka payment App Store ya Google Play se hota hai, to account delete karne se woh cancel nahi hota. Use apne store ki subscription settings mein manage ya cancel karein.")
s("acct_phone", "This phone will be cleared and signed out straight away.", "What happens on this phone after the request.", "ఈ ఫోన్‌లోని మీ డేటా వెంటనే క్లియర్ అవుతుంది, సైన్ అవుట్ అవుతుంది.", "Ee phone lo mee data ventane clear avutundi, sign out avutundi.", hi="यह फ़ोन तुरंत क्लियर हो जाएगा और इससे साइन आउट हो जाएगा।", hl="Yeh phone turant clear ho jayega aur isse sign out ho jayega.")
s("acct_needsConnection", "Deleting your account needs a connection. Connect to the internet, then try again.", "Offline: the delete button is disabled.", "ఖాతాను తొలగించడానికి ఇంటర్నెట్ కనెక్షన్ కావాలి. కనెక్ట్ అయ్యాక మళ్ళీ ప్రయత్నించండి.", "Account delete cheyadaaniki internet connection kaavali. Connect ayyaaka malli try cheyandi.", hi="अकाउंट डिलीट करने के लिए कनेक्शन चाहिए। इंटरनेट से कनेक्ट करके फिर से कोशिश करें।", hl="Account delete karne ke liye connection chahiye. Internet se connect karke phir se try karein.")
s("acct_confirmTitle", "Delete your account?", "Confirmation dialog title.", "మీ ఖాతాను తొలగించాలా?", "Mee account ni delete cheyaalaa?", hi="अपना अकाउंट डिलीट करें?", hl="Apna account delete karein?")
s("acct_confirmBody", "Your account and everything in it will be deleted in 7 days. Sign in again before then to keep it. This phone will be cleared now.", "Confirmation dialog body.", "మీ ఖాతా, అందులోని ప్రతిదీ 7 రోజుల్లో తొలగించబడతాయి. దాన్ని ఉంచుకోవాలంటే ఆలోపు మళ్ళీ సైన్ ఇన్ చేయండి. ఈ ఫోన్ ఇప్పుడే క్లియర్ అవుతుంది.", "Mee account, andulo unna pratidi 7 rojullo delete avutaayi. Daanni unchukovaalante aalopu malli sign in cheyandi. Ee phone ippude clear avutundi.", hi="आपका अकाउंट और उसमें मौजूद सब कुछ 7 दिनों में डिलीट हो जाएगा। इसे रखना हो तो उससे पहले फिर से साइन इन करें। यह फ़ोन अभी क्लियर हो जाएगा।", hl="Aapka account aur usmein maujood sab kuch 7 din mein delete ho jayega. Ise rakhna ho to usse pehle phir se sign in karein. Yeh phone abhi clear ho jayega.")
s("acct_failed", "That didn't go through, and nothing has been deleted. Try again in a moment.", "The deletion request failed. Nothing was wiped.", "అది జరగలేదు, ఏదీ తొలగించబడలేదు. కొద్దిసేపట్లో మళ్ళీ ప్రయత్నించండి.", "Adi jaragaledu, edi delete avvaledu. Koddisepatlo malli try cheyandi.", hi="यह नहीं हो पाया, और कुछ भी डिलीट नहीं हुआ है। थोड़ी देर में फिर से कोशिश करें।", hl="Yeh nahi ho paaya, aur kuch bhi delete nahi hua hai. Thodi der mein phir se try karein.")
s("acct_failedOffline", "We couldn't reach Aura, and nothing has been deleted. Check your connection and try again.", "The deletion request could not reach the server.", "Auraని చేరుకోలేకపోయాం, ఏదీ తొలగించబడలేదు. మీ కనెక్షన్ చూసుకుని మళ్ళీ ప్రయత్నించండి.", "Aura ni reach avvalekapoyaam, edi delete avvaledu. Mee connection choosukuni malli try cheyandi.", hi="Aura तक पहुँचा नहीं जा सका, और कुछ भी डिलीट नहीं हुआ है। अपना कनेक्शन जाँचें और फिर से कोशिश करें।", hl="Aura tak pahuncha nahi ja saka, aur kuch bhi delete nahi hua hai. Apna connection check karein aur phir se try karein.")
s("acct_retry", "Try again", "Retry after a failed request.", "మళ్ళీ ప్రయత్నించండి", "Malli try cheyandi", hi="फिर से कोशिश करें", hl="Phir se try karein")
s("acct_scheduledTitle", "Your account is set to be deleted", "Shown after the deletion was scheduled.", "మీ ఖాతా తొలగింపుకు సెట్ అయింది", "Mee account delete ki set ayyindi", hi="आपका अकाउंट डिलीट होना तय हो गया है", hl="Aapka account delete hona tay ho gaya hai")
s("acct_scheduledBody", "It will be deleted on {date}. Sign in again before then to keep it.", "{date} is a formatted date.", "అది {date}న తొలగించబడుతుంది. దాన్ని ఉంచుకోవాలంటే ఆలోపు మళ్ళీ సైన్ ఇన్ చేయండి.", "Adi {date} na delete avutundi. Daanni unchukovaalante aalopu malli sign in cheyandi.", STR("date"), hi="यह {date} को डिलीट हो जाएगा। इसे रखना हो तो उससे पहले फिर से साइन इन करें।", hl="Yeh {date} ko delete ho jayega. Ise rakhna ho to usse pehle phir se sign in karein.")
s("acct_phoneCleared", "This phone has been cleared and signed out.", "After the deletion was scheduled and the phone wiped.", "ఈ ఫోన్ క్లియర్ అయింది, సైన్ అవుట్ అయింది.", "Ee phone clear ayyindi, sign out ayyindi.", hi="यह फ़ोन क्लियर कर दिया गया है और इससे साइन आउट हो गया है।", hl="Yeh phone clear kar diya gaya hai aur isse sign out ho gaya hai.")
s("acct_signedOut", "You're not signed in, so there's no account to delete. What you've saved lives only on this phone.", "Delete screen opened while signed out.", "మీరు సైన్ ఇన్ చేయలేదు, కాబట్టి తొలగించడానికి ఖాతా లేదు. మీరు సేవ్ చేసినవి ఈ ఫోన్‌లో మాత్రమే ఉన్నాయి.", "Meeru sign in cheyaledu, kabatti delete cheyadaaniki account ledu. Meeru save chesinavi ee phone lo maatrame unnaayi.", hi="अभी साइन इन नहीं है, इसलिए डिलीट करने के लिए कोई अकाउंट नहीं है। आपका सेव किया हुआ सब कुछ सिर्फ़ इसी फ़ोन पर है।", hl="Abhi sign in nahi hai, isliye delete karne ke liye koi account nahi hai. Aapka save kiya hua sab kuch sirf isi phone par hai.")
s("acct_unavailable", "Account deletion isn't set up in this build.", "Dev builds without an API URL.", "ఈ బిల్డ్‌లో ఖాతా తొలగింపు ఇంకా సెట్ కాలేదు.", "Ee build lo account delete inka set avvaledu.", hi="इस बिल्ड में अकाउंट डिलीट करने की सुविधा सेट नहीं है।", hl="Is build mein account delete karne ki suvidha set nahi hai.")

# ---- Settings ---------------------------------------------------------------
s("set_comfort", "Comfort", "Settings section: motion, haptics, streak number.", "సౌకర్యం", "Comfort", hi="सहूलियत", hl="Comfort")
s("set_reduceMotion", "Reduce motion", "Switch (REQ-A11Y-08).", "కదలికలు తగ్గించండి", "Motion tagginchandi", hi="मोशन कम करें", hl="Motion kam karein")
s("set_reduceMotionNote", "Also follows your phone's setting", "Note under Reduce motion; when the phone already reduces motion the switch is on and locked.", "మీ ఫోన్ సెట్టింగ్‌ను కూడా అనుసరిస్తుంది", "Mee phone setting ni kooda follow avutundi", hi="आपके फ़ोन की सेटिंग को भी मानता है", hl="Aapke phone ki setting ko bhi follow karta hai")
s("set_haptics", "Haptics", "Switch for gentle vibration feedback.", "వైబ్రేషన్ స్పందన", "Haptics", hi="हैप्टिक्स", hl="Haptics")
s("set_hapticsNote", "Soft taps when you choose something", "Note under Haptics.", "మీరు ఏదైనా ఎంచుకున్నప్పుడు మెల్లని వైబ్రేషన్", "Meeru edaina select chesinappudu mellani vibration", hi="कुछ चुनने पर हल्का वाइब्रेशन", hl="Kuch chunne par halka vibration")
s("set_hideStreak", "Hide streak number", "Switch (F3): hides the glow-streak day count on Home.", "వరుస సంఖ్యను దాచండి", "Streak number daachandi", hi="स्ट्रीक नंबर छिपाएँ", hl="Streak number chhupayein")
s("set_hideStreakNote", "Your glow still grows. Home just won't count the days.", "Note under Hide streak number. No loss framing.", "మీ వెలుగు పెరుగుతూనే ఉంటుంది. హోమ్‌లో రోజుల లెక్క మాత్రం కనిపించదు.", "Mee glow perugutune untundi. Home lo rojula lekka maatram kanipinchadu.", hi="आपकी चमक बढ़ती रहेगी। बस होम पर दिन नहीं गिने जाएँगे।", hl="Aapka glow badhta rahega. Bas Home par din nahi gine jayenge.")
s("set_signOutTitle", "Sign out of Aura?", "Title of the sign-out warning when items haven't synced.", "Aura నుండి సైన్ అవుట్ చేయాలా?", "Aura nundi sign out cheyaalaa?", hi="Aura से साइन आउट करें?", hl="Aura se sign out karein?")
s("set_helpSafety", "Help & Safety", "Settings section: disclaimer, legal links, Grievance Officer, support.", "సహాయం & భద్రత", "Help & Safety", hi="मदद और सुरक्षा", hl="Help & Safety")
s("set_grievanceOfficer", "Grievance Officer", "Row title (F9, IT Rules). Tapping writes an email.", "ఫిర్యాదుల అధికారి", "Grievance Officer", hi="शिकायत अधिकारी", hl="Grievance Officer")
s("set_grievanceSubject", "Grievance about Aura", "Email subject pre-filled when writing to the Grievance Officer.", "Aura గురించి ఫిర్యాదు", "Aura gurinchi complaint", hi="Aura के बारे में शिकायत", hl="Aura ke baare mein shikayat")
s("set_contactSupport", "Contact support", "Row title. Tapping writes an email.", "సపోర్ట్‌ను సంప్రదించండి", "Support ni contact cheyandi", hi="सपोर्ट से संपर्क करें", hl="Support se contact karein")
s("set_supportSubject", "Aura support", "Email subject pre-filled when writing to support.", "Aura సపోర్ట్", "Aura support", hi="Aura सपोर्ट", hl="Aura support")
s("set_opensEmail", "Opens your email app", "Screen-reader hint on email rows.", "మీ ఈమెయిల్ యాప్ తెరుచుకుంటుంది", "Mee email app open avutundi", hi="आपका ईमेल ऐप खुलेगा", hl="Aapka email app khulega")
s("set_emailFailed", "We couldn't open an email app. You can write to {email}.", "No mail app could open a mailto link.", "ఈమెయిల్ యాప్‌ను తెరవలేకపోయాం. మీరు {email}కి రాయవచ్చు.", "Email app open cheyalekapoyaam. Meeru {email} ki raayochu.", STR("email"), hi="कोई ईमेल ऐप नहीं खुल पाया। {email} पर लिखें।", hl="Koi email app nahi khul paaya. {email} par likhein.")
s("acct_inProgress", "This account is already being deleted, so it can't be kept any more. This phone will be cleared and signed out.", "\"Keep my account\" came too late: the 7-day grace is over and deletion has started. Calm, no blame. The only button is Sign out.", "ఈ ఖాతా తొలగింపు ఇప్పటికే మొదలైంది, కాబట్టి దాన్ని ఇక ఉంచలేం. ఈ ఫోన్ క్లియర్ అయి సైన్ అవుట్ అవుతుంది.", "Ee account delete avvadam ippatike modalaindi, kabatti daanni inka unchalemu. Ee phone clear ayyi sign out avutundi.", hi="इस अकाउंट को डिलीट करने का काम शुरू हो चुका है, इसलिए अब इसे रखा नहीं जा सकता। यह फ़ोन क्लियर हो जाएगा और इससे साइन आउट हो जाएगा।", hl="Is account ko delete karne ka kaam shuru ho chuka hai, isliye ab ise rakha nahi ja sakta. Yeh phone clear ho jayega aur isse sign out ho jayega.")
